#include <cinux/checksum.hpp>

using namespace cinux::base;

constexpr uint16_t ChecksumOf(const unsigned char* data, size_t length) {
    InternetChecksum sum;
    sum.add(data, length);
    return sum.value();
}

constexpr uint16_t SplitChecksum(const unsigned char* data, size_t cut, size_t length) {
    InternetChecksum sum;
    sum.add(data, cut);                // 前一段在奇数位置断开，末尾字节先存着
    sum.add(data + cut, length - cut); // 后一段的第一个字节跟它拼成一对
    return sum.value();
}

void Example() {
    // RFC 1071 的样例字节：00 01 f2 03 f4 f5 f6 f7
    constexpr unsigned char kBytes[8] = {0x00, 0x01, 0xf2, 0x03, 0xf4, 0xf5, 0xf6, 0xf7};

    // 一次喂完，反码和是 0x220d
    static_assert(ChecksumOf(kBytes, 8) == 0x220d);

    // 在第三个字节后断开再喂，跨段的那一对照样拼回去，结果不变
    static_assert(SplitChecksum(kBytes, 3, 8) == 0x220d);
}

ReadWord16.example:
#include <cinux/byte_order.hpp>

using namespace cinux::base;

void Example() {
    // 一块字节：低字节在前，0x34 0x12 合起来就是 0x1234
    constexpr unsigned char kBlob[4] = {0x34, 0x12, 0x56, 0x78};

    constexpr uint16_t kWord = ReadWord16(kBlob, 0);
    // kWord = 0x1234 · 从偏移 0 起两字节按小端拼成十六位
    static_assert(kWord == 0x1234);

    // 从偏移 2 起再读一个字
    static_assert(ReadWord16(kBlob, 2) == 0x7856);
}

WriteWord16.example:
#include <cinux/byte_order.hpp>

using namespace cinux::base;

constexpr bool WritesLowByteFirst() {
    unsigned char bytes[2] = {};
    WriteWord16(bytes, 0, 0x1234);
    return bytes[0] == 0x34 && bytes[1] == 0x12;
}

void Example() {
    // 往空缓冲里写 0x1234，小端先落低字节
    unsigned char bytes[2] = {};
    WriteWord16(bytes, 0, 0x1234);
    // bytes[0] = 0x34，bytes[1] = 0x12 · 读回来还是 0x1234
    static_assert(WritesLowByteFirst());
}
